const lockSettlementSession = `-- name: LockSettlementSession :exec
SELECT pg_advisory_xact_lock(hashtextextended(
    $1::text
    || ':' || $2::bigint::text
    || ':' || encode($3::bytea, 'hex'),
    0
))
`

type LockSettlementSessionParams struct {
	UserID       string
	TorrentID    int64
	SessionToken []byte
}

// A transaction-scoped hash lock closes the empty-row race when two service
// instances receive different events for a session that has no baseline yet.
// Hash collisions only reduce concurrency; they cannot merge session state.
func (q *Queries) LockSettlementSession(ctx context.Context, arg LockSettlementSessionParams) error {
	_, err := q.db.Exec(ctx, lockSettlementSession, arg.UserID, arg.TorrentID, arg.SessionToken)
	return err
}

