const promotionRuleScopeOverlaps = `-- name: PromotionRuleScopeOverlaps :one
SELECT EXISTS (
    SELECT 1
    FROM settlement.promotion_rules
    WHERE scope_type = $1::text
      AND (
          $1::text = 'global'
          OR torrent_id = $2::bigint
      )
      AND starts_at < $3::timestamptz
      AND ends_at > $4::timestamptz
) AS overlaps
`

type PromotionRuleScopeOverlapsParams struct {
	ScopeType string
	TorrentID pgtype.Int8
	EndsAt    pgtype.Timestamptz
	StartsAt  pgtype.Timestamptz
}

func (q *Queries) PromotionRuleScopeOverlaps(ctx context.Context, arg PromotionRuleScopeOverlapsParams) (bool, error) {
	row := q.db.QueryRow(ctx, promotionRuleScopeOverlaps,
		arg.ScopeType,
		arg.TorrentID,
		arg.EndsAt,
		arg.StartsAt,
	)
	var overlaps bool
	err := row.Scan(&overlaps)
	return overlaps, err
}

